// Runtime bundle: paths, staleness hash and the page-size cap.
// The bundle is generated by scripts/dev/bundle.mjs and committed; the hash in
// its header lets a test (and the build) refuse a bundle older than its sources.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { UsageError } from '../../shared/cli.mjs';

export const SKILL_DIR = fileURLToPath(new URL('../..', import.meta.url));
export const RUNTIME_DIR = path.join(SKILL_DIR, 'template', 'runtime');
export const BUNDLE_FILE = path.join(SKILL_DIR, 'template', 'vendor', 'scene-runtime.min.js');

const KB = 1024;
// Page ceiling = ceil((bundle + 512 KB scene data + 256 KB fonts/chrome) / 64 KB) * 64 KB.
// Bundle measured 547.2 KB (560330 bytes incl. header) on 2026-10-19 with the Task 2 placeholder runtime; it grows as Tasks 7/8/10 add modules.
export const MAX_PAGE_BYTES = Math.ceil((560330 + 512 * KB + 256 * KB) / (64 * KB)) * 64 * KB; // 21 * 64 KB = 1344 KB

const HEADER_RE = /^\/\* make-scene runtime; sources sha256:([0-9a-f]{64}); three@(\S+); MIT \(see THIRD_PARTY_NOTICES\.md\) \*\//;

export function readBundle() {
  if (!fs.existsSync(BUNDLE_FILE)) {
    throw new UsageError(`scene runtime bundle missing: ${BUNDLE_FILE}. Run \`npm run bundle\` in ${SKILL_DIR}.`);
  }
  return fs.readFileSync(BUNDLE_FILE, 'utf8');
}

export function bundleHeaderHash(text) {
  const match = HEADER_RE.exec(text);
  return match ? match[1] : null;
}

function bundleHeaderThree(text) {
  const match = HEADER_RE.exec(text);
  return match ? match[2] : null;
}

/** Installed three version, or the one recorded in the committed bundle header when node_modules is absent. */
export function threeVersion() {
  const pkg = path.join(SKILL_DIR, 'node_modules', 'three', 'package.json');
  if (fs.existsSync(pkg)) return JSON.parse(fs.readFileSync(pkg, 'utf8')).version;
  const fromHeader = fs.existsSync(BUNDLE_FILE) ? bundleHeaderThree(readBundle()) : null;
  if (!fromHeader) throw new UsageError(`cannot determine three version: run \`npm ci\` in ${SKILL_DIR}.`);
  return fromHeader;
}

function runtimeFiles(dir = RUNTIME_DIR) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return runtimeFiles(full);
    return entry.name.endsWith('.js') ? [full] : [];
  });
}

/** sha256 over every template/runtime/**\/*.js (sorted by relative path, path and bytes) plus the three version. */
export function sourcesHash() {
  const hash = crypto.createHash('sha256');
  const files = runtimeFiles()
    .map((file) => path.relative(RUNTIME_DIR, file).split(path.sep).join('/'))
    .sort();
  for (const rel of files) {
    hash.update(`${rel}\0`);
    hash.update(fs.readFileSync(path.join(RUNTIME_DIR, rel)));
    hash.update('\0');
  }
  hash.update(`three@${threeVersion()}`);
  return hash.digest('hex');
}

export function bundleHeader() {
  return `/* make-scene runtime; sources sha256:${sourcesHash()}; three@${threeVersion()}; MIT (see THIRD_PARTY_NOTICES.md) */`;
}
